# Note mapping
notes = {
    'C-3': 36, 'C#3': 37, 'D-3': 38, 'D#3': 39, 'E-3': 40, 'F-3': 41, 'F#3': 42, 'G-3': 43, 'G#3': 44, 'A-3': 45, 'A#3': 46, 'B-3': 47,
    'C-4': 48, 'C#4': 49, 'D-4': 50, 'D#4': 51, 'E-4': 52, 'F-4': 53, 'F#4': 54, 'G-4': 55, 'G#4': 56, 'A-4': 57, 'A#4': 58, 'B-4': 59,
    'C-5': 60, 'C#5': 61, 'D-5': 62, 'D#5': 63, 'E-5': 64, 'F-5': 65, 'F#5': 66, 'G-5': 67, 'G#5': 68, 'A-5': 69, 'A#5': 70, 'B-5': 71,
    'C-6': 72, 'C#6': 73, 'D-6': 74, 'D#6': 75, 'E-6': 76, 'F-6': 77, 'F#6': 78, 'G-6': 79, 'G#6': 80, 'A-6': 81, 'A#6': 82, 'B-6': 83,
    '---': -1, 'OFF': -2,  # OFF might be 255 or something special
}

# XM note values: C-0=0, C#0=1, ..., B-9=119
# For note off: typically 254 or 255 depending on format
# In FT2 JSON, I think we can use integers or strings

# Let me define patterns for the keygen tune
# C minor key, 140 BPM, speed 6
# 64 rows per pattern = 4 bars at 16 rows per bar

batch = []

# Define pattern lengths
for p in range(8):
    batch.append({'name': 'pattern_set_length', 'arguments': {'pattern': p, 'rows': 64}})
    batch.append({'name': 'pattern_clear', 'arguments': {'pattern': p}})

def cell(pattern, row, channel, note=None, instrument=None, volume=None, effect=None, effect_param=None):
    args = {'pattern': pattern, 'row': row, 'channel': channel}
    if note is not None:
        if isinstance(note, str):
            args['note'] = notes.get(note, note)
        else:
            args['note'] = note
    if instrument is not None:
        args['instrument'] = instrument
    if volume is not None:
        args['volume'] = volume
    if effect is not None:
        args['effect'] = effect
    if effect_param is not None:
        args['effect_param'] = effect_param
    return {'name': 'pattern_set_cell', 'arguments': args}

# Channel allocation:
# 0: Kick drum
# 1: Hihat/Noise
# 2: Bass (Saw)
# 3: Lead melody (Square)
# 4: Arpeggio/Pluck
# 5: PWM Lead (harmonies)
# 6: Extra fills
# 7: Extra fills

# Pattern 0: Intro - bass and drums establish groove
for row in range(64):
    # Kick on beats 1 and 3 (rows 0, 16, 32, 48)
    if row % 16 == 0:
        batch.append(cell(0, row, 0, 'C-4', 4, 64))  # Kick

    # Hihat on every 8th row (offbeat feel)
    if row % 8 == 4:
        batch.append(cell(0, row, 1, 'C-4', 3, 48))  # Noise hihat

    # Bass: C-3 on downbeats, moving rhythm
    if row % 16 == 0:
        batch.append(cell(0, row, 2, 'C-3', 2, 64))  # Saw bass
    elif row % 16 == 4:
        batch.append(cell(0, row, 2, 'C-3', 2, 48))
    elif row % 16 == 8:
        batch.append(cell(0, row, 2, 'G-2', 2, 64))  # G below
    elif row % 16 == 12:
        batch.append(cell(0, row, 2, 'G-2', 2, 48))

    # Lead enters at row 32 with a simple motif
    if row == 32:
        batch.append(cell(0, row, 3, 'C-5', 1, 64))
    elif row == 36:
        batch.append(cell(0, row, 3, 'D#5', 1, 56))
    elif row == 40:
        batch.append(cell(0, row, 3, 'G-5', 1, 64))
    elif row == 44:
        batch.append(cell(0, row, 3, 'A#5', 1, 56))
    elif row == 48:
        batch.append(cell(0, row, 3, 'C-5', 1, 64))
    elif row == 52:
        batch.append(cell(0, row, 3, 'D#5', 1, 48))
    elif row == 56:
        batch.append(cell(0, row, 3, 'G-5', 1, 56))
    elif row == 60:
        batch.append(cell(0, row, 3, 'F-5', 1, 48))

# Pattern 1: Full section - main melody with bass and drums
for row in range(64):
    # Kick pattern: 1, 2.5, 3, 4 (common keygen pattern)
    if row % 16 in [0, 6, 10, 14]:
        batch.append(cell(1, row, 0, 'C-4', 4, 64))

    # Hihat: 8th notes with emphasis on offbeats
    if row % 4 == 2:
