# ========== PATTERN 7: OUTRO (loops cleanly back to intro) ==========
for row in range(64):
    # Minimal drums for clean loop
    if row % 16 == 0:
        batch.append(cell(7, row, 0, 'C-4', 4, 64))
    if row % 16 == 8:
        batch.append(cell(7, row, 2, 'C-4', 6, 48))

    # Simple bass on C
    if row % 16 == 0:
        batch.append(cell(7, row, 3, 'C-3', 2, 64))

    # Simple lead resolving to C
    if row == 0:
        batch.append(cell(7, row, 4, 'C-5', 1, 64))
    elif row == 16:
        batch.append(cell(7, row, 4, 'G-4', 1, 56))
    elif row == 32:
        batch.append(cell(7, row, 4, 'C-5', 1, 64))
    elif row == 48:
        batch.append(cell(7, row, 4, 'C-5', 1, 56))
    elif row == 56:
        batch.append(cell(7, row, 4, 'C-5', 1, 48))

    # Quiet harmony
    if row == 0:
        batch.append(cell(7, row, 5, 'G-4', 3, 48))
    elif row == 32:
        batch.append(cell(7, row, 5, 'E-4', 3, 44))

# Set order
for pos in range(8):
    batch.append({'name': 'order_set', 'arguments': {'position': pos, 'pattern': pos}})

# Song settings
batch.append({'name': 'song_set', 'arguments': {'bpm': 145, 'speed': 5, 'length': 8, 'loop_start': 0}})

with open('/workspace/create_patterns2.json', 'w') as f:
    json.dump(batch, f, indent=2)

print(f'Created {len(batch)} pattern commands')
