        batch.append(cell(7, row, 5, 'G-4', 3, 48))
    elif row == 32:
        batch.append(cell(7, row, 5, 'D#5', 3, 48))

with open('/workspace/fix_loop2.json', 'w') as f:
    json.dump(batch, f, indent=2)

print(f'Created {len(batch)} commands')
